 d2Stu:a=>set({d2Stu:+a,d2R:{},d2Fx:{},d2Done:false,d2Msg:''}),d2Ok:a=>setK('d2R',+a,'ok'),d2Fix:a=>{const r=Object.assign({},S.d2R);r[+a]='fix';const f=Object.assign({},S.d2Fx);delete f[+a];set({d2R:r,d2Fx:f});},d2Fx:a=>{const [i,j]=a.split('-').map(Number);setK('d2Fx',i,j);},
